import { randomUUID } from 'node:crypto';

/** Controlled, credentialed acceptance test against a running Relay server.
 * It never logs tokens or MCP content; it checks durable execution receipts,
 * not just text generated by the parent model.
 */
const address=process.env.RELAY_SMOKE_URL?.trim()||'';
const token=process.env.RELAY_ACCESS_TOKEN||'';
const modelKey=process.env.RELAY_SMOKE_MODEL_KEY||'';
let base:URL;
try{base=new URL(address);}catch{throw Error('Set RELAY_SMOKE_URL to the tested Relay origin');}
if((base.protocol!=='https:'&&!(base.protocol==='http:'&&
    ['localhost','127.0.0.1'].includes(base.hostname)))||
  base.username||base.password||base.search||base.hash||base.pathname!=='/'||
  token.length<24||!modelKey)throw Error('Pi smoke requires a trusted Relay URL, RELAY_ACCESS_TOKEN and RELAY_SMOKE_MODEL_KEY');
const headers={Authorization:'Bearer '+token,'Content-Type':'application/json'};
const request=async(path:string,method='GET',value?:unknown):Promise<Record<string,any>>=>{
  const response=await fetch(new URL(path,base),{
    method,headers,...(value===undefined?{}:{body:JSON.stringify(value)}),
    signal:AbortSignal.timeout(10000)});
  if(!response.ok)throw Error('Relay smoke API request failed with HTTP '+response.status+' at '+path.split('?')[0]);
  const json=await response.json() as unknown;
  if(!json||typeof json!=='object')throw Error('Relay smoke API returned invalid JSON');
  return json as Record<string,any>;
};
const status=await request('/api/status');
if(!status.piFoundation?.nativeMcp||!status.piFoundation?.subagents||
  !status.piFoundation?.childMcp)throw Error('Pi native runtime is not available on the Relay server');
if(!Array.isArray(status.models)||!status.models.some((m:{key:string})=>m.key===modelKey))
  throw Error('Selected smoke model is not configured in Relay');
const cap=await request('/api/capabilities');
if(!cap.integrations?.some((p:{id:string;enabled:boolean;configured:boolean})=>
  p.id==='github'&&p.enabled&&p.configured))
  throw Error('GitHub MCP is not enabled and configured');
const created=await request('/api/sessions','POST',{modelKey});
const conversationId=created.session?.id;
if(typeof conversationId!=='string')throw Error('Failed to create smoke conversation');
const prompt=[
  'Use exactly two separate Pi research subagents concurrently using delegate with mode=parallel.',
  'Grant each child exactly the tool mcp__github__issue_read.',
  'Child A: read issue #28 in affank1020/relay using method=get, owner=affank1020, repo=relay, issue_number=28.',
  'Child B: read issue #29 in affank1020/relay with the same method/owner/repo and issue_number=29.',
  'In each child assignment, require the child to return the verbatim issue title and a short requirements summary.',
  'Do not invent issue contents, do not use code/repository search as a substitute.',
  'Wait for both real child results; synthesize their exact titles and main requirements.'
].join('\n');
const submitted=await request('/api/sessions/'+conversationId+'/messages','POST',
  {message:prompt,requestId:randomUUID()});
const rootId=submitted.task?.id;
if(typeof rootId!=='string')throw Error('No parent Pi task was queued');
const deadline=Date.now()+180000;
let root:{state:string;result:string}|undefined;
while(Date.now()<deadline){
  const session=await request('/api/sessions/'+conversationId);
  root=(session.tasks as Array<{id:string;state:string;result:string}>|undefined)?.find(t=>t.id===rootId);
  if(root&&['completed','failed','cancelled','interrupted'].includes(root.state))break;
  await new Promise<void>(resolve=>setTimeout(resolve,2000));
}
if(root?.state!=='completed')throw Error('Parent Pi task did not complete successfully');
const events=(await request('/api/sessions/'+conversationId+'/events')).events as
  Array<{type:string;state:string;tool:string|null;childTaskId?:string;sequence:number}>;
const running=events.filter(e=>e.type==='delegation'&&e.state==='running'&&e.childTaskId);
const finished=events.filter(e=>e.type==='delegation'&&e.state==='completed'&&e.childTaskId);
const reads=events.filter(e=>e.type==='delegated_tool'&&e.state==='completed'&&
  e.tool==='mcp__github__issue_read'&&e.childTaskId);
const distinct=new Set(reads.map(e=>e.childTaskId));
if(running.length<2||distinct.size<2||finished.length<2)
  throw Error('Pi research did not produce two verified, completed child runs');
if(Math.max(...running.slice(0,2).map(e=>e.sequence))>=
  Math.min(...finished.map(e=>e.sequence)))
  throw Error('Pi children did not overlap; concurrent orchestration was not demonstrated');
const titles=[
  'Relay ChatGPT-parity foundation — Skills, MCP plugins, GitHub and memory',
  'Relay multi-agent orchestration V2 — subagents, handoffs and execution lifecycle'
];
if(!titles.every(title=>root!.result.includes(title)))
  throw Error('Parent answer omitted a verified source title');
process.stdout.write(JSON.stringify({
  ok:true,mode:'pi-native',childRuns:distinct.size,readReceipts:reads.length,
  parallel:true,parentSynthesized:true
})+'\n');
